   11	function wrapAngle(a: number): number {
   12	  let w = a % (2 * Math.PI);
   13	  if (w > Math.PI) w -= 2 * Math.PI;
   14	  if (w <= -Math.PI) w += 2 * Math.PI;
   15	  return w;
   16	}
