   18	/**
   19	 * Snap a pointer position (grid pixel space, origin at the top-left of the grid)
   20	 * to a direction and step count from the anchor cell.
   21	 * `prevDir` adds hysteresis so slow drags near a sector boundary do not flicker.
   22	 */
   23	export function snapSelection(
   24	  anchor: Cell,
   25	  px: number,
   26	  py: number,
   27	  cell: number,
   28	  rows: number,
   29	  cols: number,
   30	  prevDir: Dir | null,
   31	): Snap {
   32	  const ax = (anchor.col + 0.5) * cell;
   33	  const ay = (anchor.row + 0.5) * cell;
   34	  const dx = px - ax;
   35	  const dy = py - ay;
   36	  const dist = Math.hypot(dx, dy);
   37	
   38	  if (dist < 0.45 * cell) return { dir: prevDir, steps: 0 };
   39	
   40	  const angle = Math.atan2(dy, dx);
   41	
   42	  let dir: Dir;
   43	  if (prevDir !== null) {
   44	    const diff = wrapAngle(angle - angleOf(prevDir));
   45	    dir = Math.abs(diff) <= HYSTERESIS ? prevDir : DIR_ORDER[((Math.round(angle / SECTOR) % 8) + 8) % 8];
   46	  } else {
   47	    dir = DIR_ORDER[((Math.round(angle / SECTOR) % 8) + 8) % 8];
   48	  }
   49	
   50	  const unit = isDiagonal(dir) ? cell * Math.SQRT2 : cell;
   51	  const max = maxSteps(anchor, dir, rows, cols);
   52	  const steps = Math.min(Math.max(Math.round(dist / unit), 0), max);
   53	  return { dir, steps };
   54	}
