{"path":"src/ui/pointer.ts","content":"import type { Cell, Dir, Puzzle } from '../core/types';
import { letterAt } from '../core/generate';
import { matchWord, selectionCells, snapSelection } from '../core/select';
import type { GridView } from './grid';

export interface PointerOpts {
  view: GridView;
  puzzle: Puzzle;
  trace: HTMLElement;
  /** Normalized words not yet found in this puzzle. */
  remaining: () => Set<string>;
  /** A listed word was confirmed; `cells` is the dragged path (anchor first). */
  onFound: (word: string, cells: Cell[]) => void;
  /** Trace text to show when idle. */
  idleTrace: () => string;
}

interface DragState {
  pointerId: number;
  anchor: Cell;
  prevDir: Dir | null;
  cells: Cell[];
}

/** Attach the drag-to-select behavior to `.grid`. Pure geometry comes from core/select. */
export function attachPointer(opts: PointerOpts): void {
  const { view, puzzle, trace } = opts;
  let drag: DragState | null = null;

  function point(e: PointerEvent): { px: number; py: number } {
    const rect = view.grid.getBoundingClientRect();
    return { px: e.clientX - rect.left, py: e.clientY - rect.top };
  }

  function traceLetters(cells: Cell[]): void {
    trace.textContent = cells.map((c) => letterAt(puzzle, c)).join('');
  }

  function miss(): void {
    trace.textContent = opts.idleTrace();
    const line = view.active;
    line.style.opacity = '0';
    setTimeout(() => {
      // Only hide if this pill is still the active one and still faded
      // (a new drag within 180ms resets opacity before the timeout runs).
      if (view.active === line && line.style.opacity === '0') {
        line.style.display = 'none';
        line.style.opacity = '';
      }
    }, 180);
  }

  function onDown(e: PointerEvent): void {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const cell = view.cell;
    const { px, py } = point(e);
    const row = Math.floor(py / cell);
    const col = Math.floor(px / cell);
    if (row < 0 || col < 0 || row >= puzzle.rows || col >= puzzle.cols) return;
    view.grid.setPointerCapture(e.pointerId);
    e.preventDefault();
    const anchor = { row, col };
    drag = { pointerId: e.pointerId, anchor, prevDir: null, cells: [anchor] };
    setActive(view, [anchor]);
    traceLetters([anchor]);
  }

  function onMove(e: PointerEvent): void {
    if (!drag || e.pointerId !== drag.pointerId) return;
    const { px, py } = point(e);
    const snap = snapSelection(drag.anchor, px, py, view.cell, puzzle.rows, puzzle.cols, drag.prevDir);
    drag.prevDir = snap.dir;
    const cells = selectionCells(drag.anchor, snap);
    const a = drag.cells[drag.cells.length - 1];
    const b = cells[cells.length - 1];
    if (cells.length !== drag.cells.length || a.row !== b.row || a.col !== b.col) {
      drag.cells = cells;
      setActive(view, cells);
      traceLetters(cells);
    }
  }

  function onUp(e: PointerEvent): void {
    if (!drag || e.pointerId !== drag.pointerId) return;
    const d = drag;
    drag = null; // finalize exactly once: later release events become no-ops
    const letters = d.cells.map((c) => letterAt(puzzle, c)).join('');
    const word = matchWord(letters, opts.remaining());
    if (word) opts.onFound(word, d.cells);
    else miss();
  }

  function setActive(v: GridView, cells: Cell[]): void {
    const first = cells[0];
    const last = cells[cells.length - 1];
    v.active.setAttribute('x1', String((first.col + 0.5) * v.cell));
    v.active.setAttribute('y1', String((first.row + 0.5) * v.cell));
    v.active.setAttribute('x2', String((last.col + 0.5) * v.cell));
    v.active.setAttribute('y2', String((last.row + 0.5) * v.cell));
    v.active.setAttribute('stroke-width', String(v.cell * 0.78));
    v.active.style.opacity = '';
    v.active.style.display = '';
  }

  view.grid.addEventListener('pointerdown', onDown);
  view.grid.addEventListener('pointermove', onMove);
  view.grid.addEventListener('pointerup', onUp);
  view.grid.addEventListener('pointercancel', onUp);
  view.grid.addEventListener('lostpointercapture', onUp);
}
"}

