export function commitActivePill(view: GridView, colorIndex: number): void {
  view.active.setAttribute('class', `pill p${colorIndex % 8}`);
  view.active.style.opacity = '';
  view.found.appendChild(view.active);
  const next = svgEl('line') as SVGLineElement;
  next.setAttribute('class', 'active');
  next.style.display = 'none';
  view.found.after(next);
  view.active = next;
}

