{"content":"import type { Cell, FoundWord, Placement, Puzzle, Theme } from '../core/types';
import { pathCells } from '../core/directions';
import { GenerationError, generatePuzzle } from '../core/generate';
import { PUZZLES_PER_THEME } from '../core/levels';
import { themeById } from '../data/words';
import { getSave, saveState } from './storage';
import { buildGrid, commitActivePill, redrawPills, sizeGrid, type GridView } from './grid';
import { attachPointer } from './pointer';
import { navigate } from './router';
import { STR } from './strings';

const SEED_SUFFIXES = ['', ':1', ':2', ':3', ':4', ':5'];

/** Generate the puzzle, retrying with suffixes ':1'..':5' on GenerationError; rethrows if all fail. */
function buildPuzzle(theme: Theme, index: number): Puzzle {
  let lastErr: unknown;
  for (const suffix of SEED_SUFFIXES) {
    try {
      return generatePuzzle(theme, index, suffix);
    } catch (err) {
      lastErr = err;
    }
  }
  throw lastErr instanceof GenerationError ? lastErr : new GenerationError(`Could not generate ${theme.id}:${index}`);
}

let observer: ResizeObserver | null = null;

export function renderPuzzle(themeId: string, index: number): HTMLElement {
  const theme = themeById(themeId)!;
  const puzzle = buildPuzzle(theme, index);
  const found: FoundWord[] = [];
  const remaining = new Set(puzzle.placements.map((p) => p.word));

  const root = document.createElement('div');
  root.className = 'puzzle';

  const head = document.createElement('header');
  head.className = 'puzzle-head';
  const back = document.createElement('button');
  back.className = 'icon-btn back';
  back.setAttribute('aria-label', STR.back);
  back.textContent = '‹';
  back.addEventListener('click', () => navigate('#/'));
  const title = document.createElement('div');
  title.className = 'title';
  const strong = document.createElement('strong');
  strong.textContent = theme.name;
  const span = document.createElement('span');
  span.textContent = STR.phase(index, PUZZLES_PER_THEME);
  title.append(strong, span);
  head.append(back, title);

  const trace = document.createElement('div');
  trace.className = 'trace';
  trace.setAttribute('aria-live', 'polite');

  const area = document.createElement('div');
  area.className = 'grid-area';
  const view = buildGrid(puzzle);
  area.appendChild(view.paper);

  const words = document.createElement('div');
  words.className = 'words';
  const chips = [...puzzle.placements].sort((a, b) => a.display.localeCompare(b.display, 'pt-BR'));
  const chipByWord = new Map<string, HTMLButtonElement>();
  for (const p of chips) {
    const chip = document.createElement('button');
    chip.className = 'chip';
    chip.dataset.word = p.word;
    chip.textContent = p.display;
    chip.addEventListener('click', () => pulseHint(view, puzzle, p));
    words.appendChild(chip);
    chipByWord.set(p.word, chip);
  }

  root.append(head, trace, area, words);

  // Restore words found in this puzzle (same key as the saved progress).
  const progress = getSave().progress;
  if (progress && progress.key === puzzle.key) {
    progress.found.forEach((word, i) => {
      const p = puzzle.placements.find((pl) => pl.word === word);
      if (!p) return;
      const fw: FoundWord = { word, cells: pathCells({ row: p.row, col: p.col }, p.dir, p.word.length - 1), colorIndex: i % 8 };
      found.push(fw);
      remaining.delete(word);
      markFound(fw.word, fw.colorIndex);
    });
  }
  redrawPills(view, found);
  const idleTrace = () => (found.length > 0 ? '' : STR.dragHint);
  trace.textContent = idleTrace();

  attachPointer({ view, puzzle, trace, remaining: () => remaining, onFound, idleTrace });

  observer?.disconnect();
  const ro = new ResizeObserver(() => {
    // available box = .grid-area content box (minus its 12px/6px padding)
    // minus the .grid-paper padding (8px each side)
    sizeGrid(view, puzzle, found, area.clientWidth - 24 - 16, area.clientHeight - 12 - 16);
  });
  observer = ro;
  ro.observe(area);

  function markFound(word: string, colorIndex: number): void {
    const chip = chipByWord.get(word);
    if (chip) {
      chip.classList.add('found', `p${colorIndex % 8}`);
      chip.disabled = true;
    }
  }

  function onFound(word: string, cells: Cell[]): void {
    const colorIndex = found.length % 8;
    commitActivePill(view, colorIndex);
    found.push({ word, cells, colorIndex });
    remaining.delete(word);
    markFound(word, colorIndex);
    if (getSave().settings.haptics) navigator.vibrate?.(15);
    recordFound(puzzle.key, word);
    trace.textContent = word;
    trace.style.color = `var(--p${colorIndex % 8})`;
    setTimeout(() => {
      trace.textContent = idleTrace();
      trace.style.color = '';
    }, 600);
    if (remaining.size === 0) complete();
  }

  function complete(): void {
    recordSolved(puzzle.key);
    if (getSave().settings.haptics) navigator.vibrate?.([15, 60, 25]);
    setTimeout(showDone, 350);
  }

  function showDone(): void {
    const backdrop = document.createElement('div');
    backdrop.className = 'done-backdrop';
    const card = document.createElement('div');
    card.className = 'done-card';
    const h2 = document.createElement('h2');
    h2.textContent = STR.allFound;
    const sub = document.createElement('p');
    sub.textContent = `${theme.name}, ${STR.phase(index, PUZZLES_PER_THEME)}`;
    card.append(h2, sub);
    if (index < PUZZLES_PER_THEME) {
      const next = document.createElement('button');
      next.className = 'btn primary';
      next.textContent = STR.nextPuzzle;
      next.addEventListener('click', () => navigate(`#/p/${theme.id}/${index + 1}`));
      card.appendChild(next);
    } else {
      const msg = document.createElement('p');
      msg.className = 'done-msg';
      msg.textContent = STR.themeComplete(theme.name);
      card.appendChild(msg);
    }
    const choose = document.createElement('button');
    choose.className = 'btn';
    choose.textContent = STR.chooseTheme;
    choose.addEventListener('click', () => navigate('#/'));
    card.appendChild(choose);
    backdrop.appendChild(card);
    root.appendChild(backdrop);
  }

  return root;
}

/** Hint: pulse the first letter of the word (900ms); an already-running hint is ignored. */
function pulseHint(view: GridView, puzzle: Puzzle, p: Placement): void {
  const cellEl = view.cellEls[p.row * puzzle.cols + p.col];
  if (!cellEl || cellEl.classList.contains('hint')) return;
  cellEl.classList.add('hint');
  setTimeout(() => cellEl.classList.remove('hint'), 900);
}

/**
 * Persist a word found in the puzzle with key `key`.
 * Replaces the stored progress if it belongs to another puzzle (browsing does
 * not lose progress on another one; it is replaced only on the first found word).
 */
export function recordFound(key: string, word: string): void {
  const save = getSave();
  const progress =
    save.progress && save.progress.key === key && !save.progress.found.includes(word)
      ? { key, found: [...save.progress.found, word] }
      : { key, found: [word] };
  saveState({ ...save, progress });
}

/** Mark a puzzle solved and clear its in-progress state. */
export function recordSolved(key: string): void {
  const save = getSave();
  saveState({
    ...save,
    solved: save.solved.includes(key) ? save.solved : [...save.solved, key],
    progress: null,
  });
}
